open_signin(p_session_id uuid).def:
CREATE OR REPLACE FUNCTION public.open_signin(p_session_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_session public.training_sessions%rowtype;
  v_token   text;
  v_start   timestamptz;
  v_end     timestamptz;
begin
  if not exists (
    select 1 from public.members
    where lower(email) = lower(auth.email())
      and access && array['Department Admin','Officer','Project Admin']::text[]
  ) then
    raise exception 'You are not allowed to open a sign-in for this session.';
  end if;

  select * into v_session from public.training_sessions where id = p_session_id;
  if not found or v_session.department_id is distinct from public.my_department_id() then
    raise exception 'That training session was not found in your department.';
  end if;
  if v_session.done then
    raise exception 'This session is complete — you cannot open a sign-in.';
  end if;
  -- B4C:slice7 — a cancelled session takes no sign-in.
  if v_session.status = 'cancelled' then
    raise exception 'CANCELLED: this session was cancelled — it can''t take a sign-in.';
  end if;

  /* THE SIGN-IN WINDOW — see the file header for why both bounds exist and why
     they are asymmetric in intent.

     start_time is nullable: an all-day session with no time reads as midnight,
     so its window opens at midnight the day before. duration_min is nullable
     too: a null duration treats the session as instantaneous, so the window
     still closes 24 hours after its start rather than never.

     Central is hardcoded — see the header. */
  v_start := (v_session.date + coalesce(v_session.start_time, time '00:00'))
               at time zone 'America/Chicago';
  v_end   := v_start + make_interval(mins => coalesce(v_session.duration_min, 0));

  if now() < v_start - interval '24 hours' then
    raise exception 'This training is scheduled for %. Its sign-in can be opened from 24 hours before it starts.',
      to_char(v_start at time zone 'America/Chicago', 'FMMon FMDD, YYYY');
  end if;

  if now() > v_end + interval '24 hours' then
    raise exception 'This training was scheduled for % and its sign-in window has closed. To record who attended, mark them present on the session''s roster instead.',
      to_char(v_start at time zone 'America/Chicago', 'FMMon FMDD, YYYY');
  end if;

  -- ---- NEW IN C3 ----
  if v_session.is_offsite
     and (v_session.location_lat is null or v_session.location_lng is null) then
    raise exception 'Set this drill''s location first — you have to be on site, then tap "Use my location".';
  end if;
  -- ---- END NEW ----

  v_token := upper(substr(md5(random()::text || clock_timestamp()::text), 1, 6));
  update public.training_sessions
    set signin_token = v_token, signin_open = true
  where id = p_session_id;
  return v_token;
end;
$function$

close_signin(p_session_id uuid).def:
CREATE OR REPLACE FUNCTION public.close_signin(p_session_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (
    select 1 from public.members
    where lower(email) = lower(auth.email())
      and status in ('Active','Probationary')
      and access && array['Department Admin','Officer','Project Admin']::text[]
  ) then
    raise exception 'You are not allowed to close this sign-in.';
  end if;
  update public.training_sessions
    set signin_token = null, signin_open = false
  where id = p_session_id and department_id = public.my_department_id();
end;
$function$

pull_library_drill(p_library_id uuid).def:
CREATE OR REPLACE FUNCTION public.pull_library_drill(p_library_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    -- B4C:library slice 1 — copy a PUBLISHED catalog drill into MY department's drill plans as a DRAFT (a snapshot, L5).
    DECLARE
      v_dept uuid := public.my_department_id(); v_me uuid := public.my_member_id();
      l public.library_drills; v_id uuid;
    BEGIN
      IF v_dept IS NULL OR v_me IS NULL OR NOT coalesce(public.is_training_manager(), false) THEN
        RAISE EXCEPTION 'NOT_ALLOWED: only a Department Admin or training officer can add library drills to your plans.';
      END IF;
      SELECT * INTO l FROM public.library_drills WHERE id = p_library_id AND state = 'published';
      IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND: that drill is not in the library.' USING errcode = 'P0002'; END IF;
      SELECT id INTO v_id FROM public.drill_plans WHERE department_id = v_dept AND library_id = l.id LIMIT 1;
      IF FOUND THEN RAISE EXCEPTION 'ALREADY_PULLED: that drill is already in your plans.'; END IF;
      INSERT INTO public.drill_plans (department_id, title, category, duration_min, audience, content, status, source, library_id, created_by, updated_by)
      VALUES (v_dept, l.title, NULL, l.duration_min, l.audience, l.content, 'draft', 'library', l.id, v_me, v_me)
      RETURNING id INTO v_id;
      RETURN v_id;
    END $function$

drill_window_presence(p_session_id uuid).def:
CREATE OR REPLACE FUNCTION public.drill_window_presence(p_session_id uuid)
 RETURNS TABLE(member_id uuid, member_name text, first_in timestamp with time zone, last_out timestamp with time zone, still_open boolean, auto_closed boolean, on_roll boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    -- B4C:slice6 R1/R2 — who was ON STANDBY while this drill ran: the roll-call prefill's suggestions. READ ONLY.
    -- Window start = (date + start_time) read in America/Chicago — the same expression attested_training uses; window
    -- length = the drill's duration_min, else the flat 90. No start time -> no window -> no rows. The caller decides
    -- (pre-ticked suggestions); confirming writes plain session_attendance via the existing roster path, never this.
    declare
      v_dept  uuid := public.my_department_id();
      s       public.training_sessions%rowtype;
      v_start timestamptz; v_end timestamptz;
    begin
      if v_dept is null or not coalesce(public.is_training_manager(), false) then
        raise exception 'Only a training officer or a Department Admin can see who was on station.' using errcode = '42501';
      end if;
      select * into s from public.training_sessions where id = p_session_id and department_id = v_dept;
      if not found then raise exception 'NOT_FOUND: that session is not in your department.' using errcode = 'P0002'; end if;
      if s.start_time is null then return; end if;
      v_start := (s."date" + s.start_time) at time zone 'America/Chicago';
      v_end   := v_start + make_interval(mins => coalesce(s.duration_min, 90));
      return query
        select sp.member_id, m.name, min(sp.checked_in_at), max(sp.checked_out_at),
               bool_or(sp.checked_out_at is null), bool_or(sp.auto_closed),
               exists (select 1 from public.session_attendance sa where sa.session_id = s.id and sa.member_id = sp.member_id)
          from public.station_presence sp
          join public.members m on m.id = sp.member_id and m.department_id = s.department_id
         where sp.department_id = s.department_id
           and sp.kind = 'standby'
           and sp.checked_in_at < v_end
           and coalesce(sp.checked_out_at, now()) > v_start
         group by sp.member_id, m.name
         order by m.name;
    end;
    $function$

withdraw_session_change(p_request_id uui.def:
CREATE OR REPLACE FUNCTION public.withdraw_session_change(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    -- B4C:slice7 — the initiator takes back their own pending request (D8). Nothing about the session changes.
    declare
      v_dept uuid := public.my_department_id();
      v_me   uuid := public.my_member_id();
      r      public.training_session_requests%rowtype;
    begin
      if v_dept is null or v_me is null or not coalesce(public.is_training_manager(), false) then
        raise exception 'Only a training officer or a Department Admin can withdraw a request.' using errcode = '42501';
      end if;
      select * into r from public.training_session_requests where id = p_request_id and department_id = v_dept for update;
      if not found then raise exception 'NOT_FOUND: that request is not in your department.' using errcode = 'P0002'; end if;
      if r.state <> 'pending' then raise exception 'NOT_PENDING: this request is already %.', r.state; end if;
      if r.initiator_id <> v_me then raise exception 'NOT_YOURS: only the person who asked can withdraw it.' using errcode = '42501'; end if;
      update public.training_session_requests set state = 'withdrawn', decided_at = now() where id = r.id;
      return jsonb_build_object('request_id', r.id, 'state', 'withdrawn');
    end;
    $function$

session_change_signatures(p_request_id u.def:
CREATE OR REPLACE FUNCTION public.session_change_signatures(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    -- B4C:slice7 D4 — the two drawn signatures, on demand ("View signatures"). Same read gate as the table.
    declare
      v_dept uuid := public.my_department_id();
      r      public.training_session_requests%rowtype;
    begin
      if v_dept is null or not (coalesce(public.is_leadership(), false) or coalesce(public.is_training_manager(), false)) then
        raise exception 'Only department leadership or a training manager can view these signatures.' using errcode = '42501';
      end if;
      select * into r from public.training_session_requests where id = p_request_id and department_id = v_dept;
      if not found then raise exception 'NOT_FOUND: that request is not in your department.' using errcode = 'P0002'; end if;
      return jsonb_build_object('request_id', r.id, 'initiator_name', r.initiator_name, 'initiator_signature', r.initiator_signature,
                                'approver_name', r.approver_name, 'approver_signature', r.approver_signature);
    end;
    $function$

reject_session_change(p_request_id uuid,.def:
CREATE OR REPLACE FUNCTION public.reject_session_change(p_request_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    -- B4C:slice7 — another training manager declines a pending request, with a reason (D8). Nothing about the session changes.
    declare
      v_dept   uuid := public.my_department_id();
      v_me     uuid := public.my_member_id();
      v_reason text := btrim(coalesce(p_reason, ''));
      r        public.training_session_requests%rowtype;
    begin
      if v_dept is null or v_me is null or not coalesce(public.is_training_manager(), false) then
        raise exception 'Only a training officer or a Department Admin can decline a cancel or restore.' using errcode = '42501';
      end if;
      if length(v_reason) < 10 then raise exception 'REASON_REQUIRED: say why (at least 10 characters).'; end if;
      select * into r from public.training_session_requests where id = p_request_id and department_id = v_dept for update;
      if not found then raise exception 'NOT_FOUND: that request is not in your department.' using errcode = 'P0002'; end if;
      if r.state <> 'pending' then raise exception 'NOT_PENDING: this request is already %.', r.state; end if;
      if r.initiator_id = v_me then raise exception 'USE_WITHDRAW: you asked — withdraw it instead.'; end if;
      update public.training_session_requests
         set state = 'rejected', approver_id = v_me, approver_name = coalesce((select m.name from public.members m where m.id = v_me), 'Unknown'),
             decision_reason = v_reason, decided_at = now()
       where id = r.id;
      return jsonb_build_object('request_id', r.id, 'state', 'rejected');
    end;
    $function$

reopen_training_session(p_session_id uui.def:
CREATE OR REPLACE FUNCTION public.reopen_training_session(p_session_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    -- B4C:slice6 C6 — Reopen with a reason, logged. Same C1 hybrid as a correction (D3). Snapshots the roll so the next
    -- Finalize can log who was added/removed while it was open (D4).
    declare
      v_dept   uuid := public.my_department_id();
      v_me     uuid := public.my_member_id();
      v_today  date := (now() at time zone 'America/Chicago')::date;
      v_reason text := btrim(coalesce(p_reason, ''));
      s        public.training_sessions%rowtype;
      v_snap   uuid[];
      v_audit  uuid;
    begin
      if v_dept is null or v_me is null or not coalesce(public.is_training_manager(), false) then
        raise exception 'Only a training officer or a Department Admin can reopen a session.' using errcode = '42501';
      end if;
      select * into s from public.training_sessions where id = p_session_id and department_id = v_dept for update;
      if not found then raise exception 'NOT_FOUND: that session is not in your department.' using errcode = 'P0002'; end if;
      if not s.done then raise exception 'NOT_FINALIZED: this session is not finalized.'; end if;
      if length(v_reason) < 10 then raise exception 'REASON_REQUIRED: say why (at least 10 characters).'; end if;
      if s."date" < v_today - 14
         and not exists (select 1 from public.members m where m.id = v_me and m.department_id = v_dept
                           and m.status in ('Active', 'Probationary') and m.access && array['Department Admin']::text[]) then
        raise exception 'DA_ONLY: reopening a drill more than 14 days old is for a Department Admin.' using errcode = '42501';
      end if;
      select coalesce(array_agg(sa.member_id order by sa.member_id), '{}') into v_snap
        from public.session_attendance sa where sa.session_id = s.id;
      update public.training_sessions set done = false where id = s.id;
      perform public.recompute_training_plan_last_iso(s.plan_id);
      insert into public.training_session_audit (department_id, session_id, action, actor_id, actor_name, reason, changes,
                                                 roster_before, roster_after, roster_snapshot)
      values (v_dept, s.id, 'reopen', v_me, coalesce((select m.name from public.members m where m.id = v_me), 'Unknown'),
              v_reason, jsonb_build_object('done', jsonb_build_object('old', true, 'new', false)),
              cardinality(v_snap), cardinality(v_snap), v_snap)
      returning id into v_audit;
      return jsonb_build_object('audit_id', v_audit, 'roster', cardinality(v_snap));
    end;
    $function$

approve_session_change(p_request_id uuid.def:
CREATE OR REPLACE FUNCTION public.approve_session_change(p_request_id uuid, p_signature text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    -- B4C:slice7 — step 2 of 2: a DIFFERENT training manager, signed in on their own account, approves with their own
    -- drawn signature; the cancel / restore takes effect in this transaction and is logged in training_session_audit.
    -- A request that is no longer valid (drill date passed; session attended / finalized / already in the target state)
    -- is EXPIRED and returned as such (D1) — not raised, so the expiry persists.
    declare
      v_dept  uuid := public.my_department_id();
      v_me    uuid := public.my_member_id();
      v_today date := (now() at time zone 'America/Chicago')::date;
      r       public.training_session_requests%rowtype;
      s       public.training_sessions%rowtype;
      v_new   text; v_n integer; v_audit uuid; v_name text;
    begin
      if v_dept is null or v_me is null or not coalesce(public.is_training_manager(), false) then
        raise exception 'Only a training officer or a Department Admin can sign off a cancel or restore.' using errcode = '42501';
      end if;
      if p_signature is null or p_signature not like 'data:image/png;base64,%' or length(p_signature) > 204800 then
        raise exception 'BAD_SIGNATURE: draw your signature (a PNG, up to 200 KB).';
      end if;
      select * into r from public.training_session_requests where id = p_request_id and department_id = v_dept for update;
      if not found then raise exception 'NOT_FOUND: that request is not in your department.' using errcode = 'P0002'; end if;
      if r.state <> 'pending' then raise exception 'NOT_PENDING: this request is already %.', r.state; end if;
      if r.initiator_id = v_me then
        raise exception 'SAME_PERSON: a second training manager has to sign off — not the one who asked.' using errcode = '42501';
      end if;
      select * into s from public.training_sessions where id = r.session_id for update;
      v_new := case r.kind when 'cancel' then 'cancelled' else 'scheduled' end;
      if s."date" < v_today or s.done or s.status = v_new
         or exists (select 1 from public.session_attendance sa where sa.session_id = s.id) then
        update public.training_session_requests set state = 'expired', decided_at = now() where id = r.id;
        return jsonb_build_object('request_id', r.id, 'state', 'expired');
      end if;
      select count(*) into v_n from public.session_attendance where session_id = s.id;   -- 0 by the check above
      v_name := coalesce((select m.name from public.members m where m.id = v_me), 'Unknown');
      perform set_config('b4c.session_correction', 'on', true);
      update public.training_sessions
         set status = v_new,
             signin_open = case when v_new = 'cancelled' then false else signin_open end,      -- D5
             signin_token = case when v_new = 'cancelled' then null else signin_token end
       where id = s.id;
      perform set_config('b4c.session_correction', '', true);
      update public.training_session_requests
         set state = 'approved', approver_id = v_me, approver_name = v_name, approver_signature = p_signature, decided_at = now()
       where id = r.id;
      insert into public.training_session_audit (department_id, session_id, action, actor_id, actor_name, reason, changes, roster_before, roster_after)
      values (v_dept, s.id, r.kind, v_me, v_name, r.reason,
              jsonb_build_object('status', jsonb_build_object('old', s.status, 'new', v_new), 'request_id', r.id,
                                 'initiator', jsonb_build_object('id', r.initiator_id, 'name', r.initiator_name)),
              v_n, v_n)
      returning id into v_audit;
      return jsonb_build_object('request_id', r.id, 'state', 'approved', 'status', v_new, 'audit_id', v_audit);
    end;
    $function$

attach_drill_plan_to_session(p_plan_id u.def:
CREATE OR REPLACE FUNCTION public.attach_drill_plan_to_session(p_plan_id uuid, p_session_id uuid)
 RETURNS session_plans
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- B4C:drill plans — attach a library plan to a training session in the caller's OWN department, as an ordinary
  -- session_plans row (the existing View plan renders its ai_text). One attachment per (session, plan).
  declare v_dept uuid := public.my_department_id(); v_p public.drill_plans; v_row public.session_plans;
          v_c jsonb; v_who text; L text[] := array[]::text[]; s jsonb; i int := 0;
  begin
    if v_dept is null or not coalesce(public.is_training_manager(), false) then
      raise exception 'Only a Department Admin or training officer can attach drill plans.';
    end if;
    select * into v_p from public.drill_plans where id = p_plan_id and department_id = v_dept for update;
    if not found then raise exception 'That drill plan is not in your department.'; end if;
    if not exists (select 1 from public.training_sessions where id = p_session_id and department_id = v_dept) then
      raise exception 'That session is not in your department.';
    end if;
    -- B4C:slice7 — no plans onto a cancelled session (R7).
    if exists (select 1 from public.training_sessions where id = p_session_id and status = 'cancelled') then
      raise exception 'CANCELLED: that session was cancelled — restore it before attaching a plan.';
    end if;
    if exists (select 1 from public.session_plans where session_id = p_session_id and drill_plan_id = p_plan_id) then
      raise exception 'That plan is already attached to this session.';
    end if;
    v_c := v_p.content;
    -- the Quick Run Sheet, then the full plan — the layout serializeDrillPlan writes and the plan viewer splits on
    L := L || '## Quick Run Sheet'::text;
    if v_p.duration_min is not null then L := L || ''::text || ('Total time: ' || v_p.duration_min || ' min'); end if;
    if jsonb_typeof(v_c -> 'run_of_show') = 'array' then
      for s in select x from jsonb_array_elements(v_c -> 'run_of_show') x loop
        i := i + 1;
        if jsonb_typeof(s) = 'object' then
          L := L || ''::text || ('**' || i || '. ' || coalesce(nullif(s ->> 't', ''), 'Step') || '**');
          if coalesce(s ->> 'd', '') <> '' then L := L || ('- ' || (s ->> 'd')); end if;
        else
          L := L || ''::text || ('**' || i || '. ' || (s #>> '{}') || '**');
        end if;
      end loop;
    end if;
    if jsonb_typeof(v_c -> 'safety') = 'array' and jsonb_array_length(v_c -> 'safety') > 0 then
      L := L || ''::text || '**Safety first:**'::text || array(select '- ' || (x #>> '{}') from jsonb_array_elements(v_c -> 'safety') x);
    end if;
    L := L || ''::text || ('## ' || v_p.title || ' — Drill Plan');
    if coalesce(v_c ->> 'summary', '') <> '' then L := L || ''::text || (v_c ->> 'summary'); end if;
    if v_p.duration_min is not null then L := L || ''::text || ('Duration: ' || v_p.duration_min || ' minutes'); end if;
    if jsonb_typeof(v_c -> 'objectives') = 'array' and jsonb_array_length(v_c -> 'objectives') > 0 then
      L := L || ''::text || '## Objectives'::text || array(select '- ' || (x #>> '{}') from jsonb_array_elements(v_c -> 'objectives') x);
    end if;
    if jsonb_typeof(v_c -> 'safety') = 'array' and jsonb_array_length(v_c -> 'safety') > 0 then
      L := L || ''::text || '## Safety notes'::text || array(select '- ' || (x #>> '{}') from jsonb_array_elements(v_c -> 'safety') x);
    end if;
    if jsonb_typeof(v_c -> 'materials') = 'array' and jsonb_array_length(v_c -> 'materials') > 0 then
      L := L || ''::text || '## Equipment'::text || array(select '- ' || (x #>> '{}') from jsonb_array_elements(v_c -> 'materials') x);
    end if;
    select name into v_who from public.members where id = public.my_member_id();
    insert into public.session_plans (department_id, session_id, title, source, ai_text, created_by, drill_plan_id)
    values (v_dept, p_session_id, v_p.title, 'ai', array_to_string(L, E'\n'), coalesce(v_who, 'Unknown'), p_plan_id)
    returning * into v_row;
    return v_row;
  end;
  $function$

finalize_training_session(p_session_id u.def:
CREATE OR REPLACE FUNCTION public.finalize_training_session(p_session_id uuid, p_duration_min integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    -- B4C:slice6 C4 — what the client's finalize does today (done, plus a FIRST length), logged. R4: a category's
    -- last_iso becomes greatest(existing, the drill's date) — and only when the roll is non-empty. If the session was
    -- reopened, the roster change since that Reopen is logged here (D4).
    declare
      v_dept  uuid := public.my_department_id();
      v_me    uuid := public.my_member_id();
      s       public.training_sessions%rowtype;
      v_dur   integer;
      v_now   uuid[]; v_snap uuid[]; v_last text;
      v_add   uuid[] := '{}'; v_rem uuid[] := '{}';
      v_diff  jsonb := jsonb_build_object('done', jsonb_build_object('old', false, 'new', true));
      v_audit uuid;
    begin
      if v_dept is null or v_me is null or not coalesce(public.is_training_manager(), false) then
        raise exception 'Only a training officer or a Department Admin can finalize a session.' using errcode = '42501';
      end if;
      select * into s from public.training_sessions where id = p_session_id and department_id = v_dept for update;
      if not found then raise exception 'NOT_FOUND: that session is not in your department.' using errcode = 'P0002'; end if;
      if s.done then raise exception 'ALREADY_FINALIZED: this session is already finalized.'; end if;
      -- B4C:slice7 — a cancelled drill didn't happen: nothing to finalize.
      if s.status = 'cancelled' then raise exception 'CANCELLED: this session was cancelled — restore it before finalizing.'; end if;
      if s.signin_open then raise exception 'SIGNIN_OPEN: close the QR sign-in first.'; end if;
      if p_duration_min is not null then
        if p_duration_min < 1 or p_duration_min > 1440 then raise exception 'BAD_VALUE: a length is 1–1440 minutes.'; end if;
        if s.duration_min is not null and s.duration_min <> p_duration_min then
          raise exception 'USE_CORRECT: this drill already has a length — change it with Correct.';
        end if;
      end if;
      v_dur := coalesce(s.duration_min, p_duration_min);
      if v_dur is distinct from s.duration_min then
        v_diff := v_diff || jsonb_build_object('duration_min', jsonb_build_object('old', s.duration_min, 'new', v_dur));
      end if;
      select coalesce(array_agg(sa.member_id order by sa.member_id), '{}') into v_now
        from public.session_attendance sa where sa.session_id = s.id;
      -- the latest log entry for this session: if it is a Reopen, compare the roll now with the roll then
      select a.action, a.roster_snapshot into v_last, v_snap
        from public.training_session_audit a where a.session_id = s.id order by a.seq desc limit 1;
      if v_last = 'reopen' then
        select coalesce(array_agg(x order by x), '{}') into v_add from unnest(v_now) x where x <> all (coalesce(v_snap, '{}'));
        select coalesce(array_agg(x order by x), '{}') into v_rem from unnest(coalesce(v_snap, '{}')) x where x <> all (v_now);
      end if;
      update public.training_sessions set done = true, duration_min = v_dur where id = s.id;
      if s.plan_id is not null and cardinality(v_now) > 0 then
        update public.training_plans set last_iso = greatest(coalesce(last_iso, s."date"), s."date") where id = s.plan_id;
      end if;
      insert into public.training_session_audit (department_id, session_id, action, actor_id, actor_name, reason, changes,
                                                 roster_added, roster_removed, roster_before, roster_after)
      values (v_dept, s.id, 'finalize', v_me, coalesce((select m.name from public.members m where m.id = v_me), 'Unknown'),
              null, v_diff, v_add, v_rem,
              cardinality(v_now) - cardinality(v_add) + cardinality(v_rem), cardinality(v_now))
      returning id into v_audit;
      return jsonb_build_object('audit_id', v_audit, 'present', cardinality(v_now), 'duration_min', v_dur,
                                'roster_added', to_jsonb(v_add), 'roster_removed', to_jsonb(v_rem));
    end;
    $function$

request_session_change(p_session_id uuid.def:
CREATE OR REPLACE FUNCTION public.request_session_change(p_session_id uuid, p_kind text, p_reason text, p_signature text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    -- B4C:slice7 — step 1 of 2: a training manager asks to CANCEL or RESTORE an upcoming, unattended, unfinalized session,
    -- with a reason and their drawn signature. Nothing about the session changes until a DIFFERENT manager approves.
    declare
      v_dept   uuid := public.my_department_id();
      v_me     uuid := public.my_member_id();
      v_today  date := (now() at time zone 'America/Chicago')::date;
      v_reason text := btrim(coalesce(p_reason, ''));
      s        public.training_sessions%rowtype;
      v_id     uuid;
    begin
      if v_dept is null or v_me is null or not coalesce(public.is_training_manager(), false) then
        raise exception 'Only a training officer or a Department Admin can ask to cancel or restore a session.' using errcode = '42501';
      end if;
      if p_kind is null or p_kind not in ('cancel', 'restore') then raise exception 'BAD_KIND: cancel or restore.'; end if;
      if length(v_reason) < 10 then raise exception 'REASON_REQUIRED: say why (at least 10 characters).'; end if;
      if p_signature is null or p_signature not like 'data:image/png;base64,%' or length(p_signature) > 204800 then
        raise exception 'BAD_SIGNATURE: draw your signature (a PNG, up to 200 KB).';
      end if;
      select * into s from public.training_sessions where id = p_session_id and department_id = v_dept for update;
      if not found then raise exception 'NOT_FOUND: that session is not in your department.' using errcode = 'P0002'; end if;
      if s."date" < v_today then raise exception 'NOT_UPCOMING: only an upcoming session can be cancelled or restored.'; end if;
      if s.done then raise exception 'FINALIZED: this session is finalized — it happened.'; end if;
      if exists (select 1 from public.session_attendance sa where sa.session_id = s.id) then
        raise exception 'ATTENDED: someone is on this session''s roll — it happened; use Correct instead.';
      end if;
      if p_kind = 'cancel' and s.status = 'cancelled' then raise exception 'ALREADY_CANCELLED: this session is already cancelled.'; end if;
      if p_kind = 'restore' and s.status <> 'cancelled' then raise exception 'NOT_CANCELLED: only a cancelled session can be restored.'; end if;
      if exists (select 1 from public.training_session_requests r where r.session_id = s.id and r.state = 'pending') then
        raise exception 'PENDING: a sign-off is already waiting on this session.';
      end if;
      insert into public.training_session_requests (department_id, session_id, kind, reason, initiator_id, initiator_name, initiator_signature)
      values (v_dept, s.id, p_kind, v_reason, v_me, coalesce((select m.name from public.members m where m.id = v_me), 'Unknown'), p_signature)
      returning id into v_id;
      return jsonb_build_object('request_id', v_id, 'state', 'pending', 'kind', p_kind);
    end;
    $function$

correct_training_session(p_session_id uu.def:
CREATE OR REPLACE FUNCTION public.correct_training_session(p_session_id uuid, p_changes jsonb, p_add uuid[], p_remove uuid[], p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    -- B4C:slice6 — the gated, logged correction of a LOCKED session (finalized, sign-in open, or anyone on the roll).
    -- C1 hybrid: a training manager within 14 days of the drill (Central); older = Department Admin only (D1: the ROLE,
    -- never Project Admin). C2: a reason of 10+ characters. Fields: §2a whitelist only. Roster: add/remove in the same
    -- transaction; the membership-window triggers still run, and a refusal there aborts the whole call (nothing written).
    declare
      v_dept   uuid := public.my_department_id();
      v_me     uuid := public.my_member_id();
      v_today  date := (now() at time zone 'America/Chicago')::date;
      v_reason text := btrim(coalesce(p_reason, ''));
      v_chg    jsonb := coalesce(p_changes, '{}'::jsonb);
      v_keys   constant text[] := array['title', 'date', 'start_time', 'duration_min', 'audience', 'plan_id',
                                        'counts_toward_attendance', 'is_meeting', 'is_offsite', 'location_label'];
      s        public.training_sessions%rowtype;
      v_bad    text[];
      n_title text; n_date date; n_start time; n_dur integer; n_aud text; n_plan uuid;
      n_counts boolean; n_meet boolean; n_off boolean; n_label text;
      v_diff   jsonb := '{}'::jsonb;
      v_add    uuid[]; v_rem uuid[];
      v_before integer; v_after integer;
      v_audit  uuid;
    begin
      if v_dept is null or v_me is null or not coalesce(public.is_training_manager(), false) then
        raise exception 'Only a training officer or a Department Admin can correct a session.' using errcode = '42501';
      end if;
      select * into s from public.training_sessions where id = p_session_id and department_id = v_dept for update;
      if not found then raise exception 'NOT_FOUND: that session is not in your department.' using errcode = 'P0002'; end if;
      -- B4C:slice7 — a cancelled session is restored (two-person), not corrected.
      if s.status = 'cancelled' then raise exception 'CANCELLED: this session was cancelled — restore it before correcting it.'; end if;
      if not (s.done or s.signin_open or exists (select 1 from public.session_attendance sa where sa.session_id = s.id)) then
        raise exception 'NOT_LOCKED: this session can still be edited normally — no correction needed.';
      end if;
      if length(v_reason) < 10 then raise exception 'REASON_REQUIRED: say why (at least 10 characters).'; end if;
      if jsonb_typeof(v_chg) <> 'object' then raise exception 'BAD_CHANGES: changes must be a JSON object.'; end if;
      select array_agg(k order by k) into v_bad from jsonb_object_keys(v_chg) k where k <> all (v_keys);
      if v_bad is not null then raise exception 'UNKNOWN_FIELD: % cannot be corrected here.', array_to_string(v_bad, ', '); end if;

      -- the corrected values (an absent key = unchanged)
      n_title  := case when v_chg ? 'title'        then btrim(v_chg->>'title') else s.title end;
      n_date   := case when v_chg ? 'date'         then (v_chg->>'date')::date else s."date" end;
      n_start  := case when v_chg ? 'start_time'   then nullif(v_chg->>'start_time', '')::time else s.start_time end;
      n_dur    := case when v_chg ? 'duration_min' then nullif(v_chg->>'duration_min', '')::integer else s.duration_min end;
      n_aud    := case when v_chg ? 'audience'     then v_chg->>'audience' else s.audience end;
      n_plan   := case when v_chg ? 'plan_id'      then nullif(v_chg->>'plan_id', '')::uuid else s.plan_id end;
      n_counts := case when v_chg ? 'counts_toward_attendance' then (v_chg->>'counts_toward_attendance')::boolean else s.counts_toward_attendance end;
      n_meet   := case when v_chg ? 'is_meeting'   then (v_chg->>'is_meeting')::boolean else s.is_meeting end;
      n_off    := case when v_chg ? 'is_offsite'   then (v_chg->>'is_offsite')::boolean else s.is_offsite end;
      n_label  := case when v_chg ? 'location_label' then nullif(btrim(v_chg->>'location_label'), '') else s.location_label end;
      if n_title is null or n_title = '' then raise exception 'BAD_VALUE: a session needs a title.'; end if;
      if n_date is null then raise exception 'BAD_VALUE: a session needs a date.'; end if;
      if n_counts is null or n_off is null then raise exception 'BAD_VALUE: counts_toward_attendance / is_offsite cannot be blank.'; end if;
      if n_dur is not null and (n_dur < 1 or n_dur > 1440) then raise exception 'BAD_VALUE: a length is 1–1440 minutes.'; end if;
      if n_aud is null or n_aud not in ('everyone', 'leadership', 'board') then raise exception 'BAD_VALUE: unknown audience.'; end if;
      if n_plan is distinct from s.plan_id and n_plan is not null
         and not exists (select 1 from public.training_plans tp where tp.id = n_plan and tp.department_id = v_dept) then
        raise exception 'BAD_VALUE: that training category is not in your department.';
      end if;
      if n_aud <> 'everyone' then n_meet := false; end if;      -- only an everyone session carries the meeting flag (client rule)
      if not n_off then n_label := null; end if;                -- off -> no label / coordinates (coords CHECK)

      -- C1 hybrid (D2: the earlier of the current and corrected date)
      if least(s."date", n_date) < v_today - 14
         and not exists (select 1 from public.members m where m.id = v_me and m.department_id = v_dept
                           and m.status in ('Active', 'Probationary') and m.access && array['Department Admin']::text[]) then
        raise exception 'DA_ONLY: correcting a drill more than 14 days old is for a Department Admin.' using errcode = '42501';
      end if;

      -- old -> new, only what actually changes
      if n_title  is distinct from s.title        then v_diff := v_diff || jsonb_build_object('title',        jsonb_build_object('old', s.title, 'new', n_title)); end if;
      if n_date   is distinct from s."date"       then v_diff := v_diff || jsonb_build_object('date',         jsonb_build_object('old', s."date", 'new', n_date)); end if;
      if n_start  is distinct from s.start_time   then v_diff := v_diff || jsonb_build_object('start_time',   jsonb_build_object('old', s.start_time, 'new', n_start)); end if;
      if n_dur    is distinct from s.duration_min then v_diff := v_diff || jsonb_build_object('duration_min', jsonb_build_object('old', s.duration_min, 'new', n_dur)); end if;
      if n_aud    is distinct from s.audience     then v_diff := v_diff || jsonb_build_object('audience',     jsonb_build_object('old', s.audience, 'new', n_aud)); end if;
      if n_plan   is distinct from s.plan_id      then v_diff := v_diff || jsonb_build_object('plan_id',      jsonb_build_object('old', s.plan_id, 'new', n_plan)); end if;
      if n_counts is distinct from s.counts_toward_attendance then v_diff := v_diff || jsonb_build_object('counts_toward_attendance', jsonb_build_object('old', s.counts_toward_attendance, 'new', n_counts)); end if;
      if n_meet   is distinct from s.is_meeting   then v_diff := v_diff || jsonb_build_object('is_meeting',   jsonb_build_object('old', s.is_meeting, 'new', n_meet)); end if;
      if n_off    is distinct from s.is_offsite   then v_diff := v_diff || jsonb_build_object('is_offsite',   jsonb_build_object('old', s.is_offsite, 'new', n_off)); end if;
      if n_label  is distinct from s.location_label then v_diff := v_diff || jsonb_build_object('location_label', jsonb_build_object('old', s.location_label, 'new', n_label)); end if;
      if not n_off and (s.location_lat is not null or s.location_lng is not null) then
        v_diff := v_diff || jsonb_build_object('location', jsonb_build_object('old', jsonb_build_object('lat', s.location_lat, 'lng', s.location_lng, 'radius_m', s.location_radius_m), 'new', null));
      end if;

      -- roster deltas: deduped, disjoint, truthful (no "adding" someone already there, no "removing" someone absent)
      select coalesce(array_agg(distinct x order by x), '{}') into v_add from unnest(coalesce(p_add, '{}')) x where x is not null;
      select coalesce(array_agg(distinct x order by x), '{}') into v_rem from unnest(coalesce(p_remove, '{}')) x where x is not null;
      if v_add && v_rem then raise exception 'BAD_ROSTER: a member cannot be both added and removed.'; end if;
      if exists (select 1 from unnest(v_add) x where not exists (select 1 from public.members m where m.id = x and m.department_id = v_dept)) then
        raise exception 'BAD_ROSTER: someone being added is not a member of your department.';
      end if;
      if exists (select 1 from unnest(v_add) x where exists (select 1 from public.session_attendance sa where sa.session_id = s.id and sa.member_id = x)) then
        raise exception 'BAD_ROSTER: someone being added is already on the roll.';
      end if;
      if exists (select 1 from unnest(v_rem) x where not exists (select 1 from public.session_attendance sa where sa.session_id = s.id and sa.member_id = x)) then
        raise exception 'BAD_ROSTER: someone being removed is not on the roll.';
      end if;
      if v_diff = '{}'::jsonb and cardinality(v_add) = 0 and cardinality(v_rem) = 0 then
        raise exception 'NO_CHANGE: nothing to correct.';
      end if;

      select count(*) into v_before from public.session_attendance where session_id = s.id;
      perform set_config('b4c.session_correction', 'on', true);
      -- removals BEFORE the date moves (someone leaving the roll must not block a date their window excludes);
      -- additions AFTER (their window is checked against the corrected date)
      delete from public.session_attendance where session_id = s.id and member_id = any (v_rem);
      if v_diff <> '{}'::jsonb then
        update public.training_sessions
           set title = n_title, "date" = n_date, start_time = n_start, duration_min = n_dur, audience = n_aud, plan_id = n_plan,
               counts_toward_attendance = n_counts, is_meeting = n_meet, is_offsite = n_off, location_label = n_label,
               location_lat = case when n_off then location_lat end,
               location_lng = case when n_off then location_lng end,
               location_radius_m = case when n_off then location_radius_m end
         where id = s.id;
      end if;
      insert into public.session_attendance (department_id, session_id, member_id, checked_in_at)
      select v_dept, s.id, x, now() from unnest(v_add) x;
      perform set_config('b4c.session_correction', '', true);
      select count(*) into v_after from public.session_attendance where session_id = s.id;

      perform public.recompute_training_plan_last_iso(s.plan_id);
      if n_plan is distinct from s.plan_id then perform public.recompute_training_plan_last_iso(n_plan); end if;

      insert into public.training_session_audit (department_id, session_id, action, actor_id, actor_name, reason, changes,
                                                 roster_added, roster_removed, roster_before, roster_after)
      values (v_dept, s.id, 'correct', v_me, coalesce((select m.name from public.members m where m.id = v_me), 'Unknown'),
              v_reason, v_diff, v_add, v_rem, v_before, v_after)
      returning id into v_audit;
      return jsonb_build_object('audit_id', v_audit, 'changes', v_diff, 'roster_added', to_jsonb(v_add),
                                'roster_removed', to_jsonb(v_rem), 'roster_before', v_before, 'roster_after', v_after);
    end;
    $function$

dept_member_iso_hours_by_month(p_member_.def:
CREATE OR REPLACE FUNCTION public.dept_member_iso_hours_by_month(p_member_id uuid, p_starts timestamp with time zone[], p_ends timestamp with time zone[])
 RETURNS TABLE(idx integer, credited numeric)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  n integer := coalesce(array_length(p_starts, 1), 0);
begin
  if p_member_id is null then
    raise exception 'A member is required.';
  end if;
  if n <> coalesce(array_length(p_ends, 1), 0) then
    raise exception 'Starts and ends must be the same length.';
  end if;
  if n > 24 then
    raise exception 'At most 24 windows per call.';
  end if;
  -- idx is 1-based, matching the input arrays. Every window gets a row, even an
  -- empty one (credited 0), so the client never mistakes a missing row for a
  -- failed read.
  return query
  select i,
         coalesce((select h.iso_total_hours
                     from public.dept_iso_hours(p_starts[i], p_ends[i]) h
                    where h.member_id = p_member_id), 0)::numeric
    from generate_series(1, n) as i
   order by i;
end;
$function$

set_session_location(p_session_id uuid,.def:
CREATE OR REPLACE FUNCTION public.set_session_location(p_session_id uuid, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision, p_radius_m integer DEFAULT NULL::integer, p_label text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_dept    uuid := public.my_department_id();
  v_session public.training_sessions%rowtype;
  v_radius  integer;
begin
  if not exists (
    select 1 from public.members
    where lower(email) = lower(auth.email())
      and access && array['Department Admin','Officer','Project Admin']::text[]
  ) then
    raise exception 'You are not allowed to set the location for this session.';
  end if;

  select * into v_session from public.training_sessions where id = p_session_id;
  if not found or v_session.department_id is distinct from v_dept then
    raise exception 'That training session was not found in your department.';
  end if;
  if v_session.done then
    raise exception 'This session is complete — its location can no longer be changed.';
  end if;
  -- B4C:slice7 — a cancelled session's location is frozen with it.
  if v_session.status = 'cancelled' then
    raise exception 'CANCELLED: this session was cancelled — restore it before changing its location.';
  end if;

  -- clear: back to verifying against the station. Allowed whatever the flag says.
  if p_lat is null and p_lng is null then
    update public.training_sessions
       set location_lat = null, location_lng = null,
           location_radius_m = null, location_label = null
     where id = p_session_id;
    return;
  end if;

  if p_lat is null or p_lng is null then
    raise exception 'We could not read your location — try again, or leave the drill at the station.';
  end if;

  -- ---- NEW IN C3: only an off-site drill may carry a location ----
  if not v_session.is_offsite then
    raise exception 'Mark this drill as off-site before setting its location.';
  end if;
  -- ---- END NEW ----

  -- store the radius explicitly so the record is self-describing later
  v_radius := coalesce(p_radius_m,
                       (select station_radius_m from public.departments where id = v_dept),
                       400);

  update public.training_sessions
     set location_lat      = p_lat,
         location_lng      = p_lng,
         location_radius_m = v_radius,
         location_label    = nullif(btrim(coalesce(p_label, '')), '')
   where id = p_session_id;
end;
$function$

member_check_in(p_session_id uuid, p_tok.def:
CREATE OR REPLACE FUNCTION public.member_check_in(p_session_id uuid, p_token text, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision, p_accuracy double precision DEFAULT NULL::double precision)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_session  public.training_sessions%ROWTYPE;
  v_member   uuid := public.my_member_id();
  v_dept     uuid := public.my_department_id();
  v_recorded boolean := false;
  v_verified boolean := false;
  v_pinned   boolean := true;   -- fail closed if the department row does not resolve
BEGIN
  IF v_member IS NULL OR v_dept IS NULL THEN
    RAISE EXCEPTION 'We could not match your login to a member record.';
  END IF;

  SELECT * INTO v_session FROM public.training_sessions WHERE id = p_session_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'That training session was not found.';
  END IF;

  IF v_session.department_id IS DISTINCT FROM v_dept THEN
    RAISE EXCEPTION 'That session is not in your department.';
  END IF;

  IF v_session.done THEN
    RAISE EXCEPTION 'This session is complete — attendance is locked.';
  END IF;
  -- B4C:slice7 — nobody checks in to a cancelled session.
  IF v_session.status = 'cancelled' THEN
    RAISE EXCEPTION 'CANCELLED: this session was cancelled — there is nothing to check in to.';
  END IF;

  -- ---- ADDED: the sign-in must be OPEN, not merely hold a matching code ----
  -- Without this, "is this sign-in open?" is answered indirectly, by whether
  -- some other function remembered to clear the token when closing. That is an
  -- invariant maintained by one writer and breakable by any direct UPDATE.
  IF NOT coalesce(v_session.signin_open, false) THEN
    RAISE EXCEPTION 'Sign-in for this session has closed — ask your training officer to reopen it.';
  END IF;
  -- ---- END ADDED ----

  IF v_session.signin_token IS NULL OR v_session.signin_token <> p_token THEN
    RAISE EXCEPTION 'Invalid or expired sign-in code — scan the current QR.';
  END IF;

  INSERT INTO public.session_attendance (department_id, session_id, member_id, checked_in_at)
  VALUES (v_dept, p_session_id, v_member, now())
  ON CONFLICT (session_id, member_id) DO NOTHING;
  v_recorded := FOUND;

  -- ---- CHANGED IN C3: branch on the FLAG, not on whether coordinates exist ----
  IF v_session.is_offsite THEN
    IF v_session.location_lat IS NOT NULL AND v_session.location_lng IS NOT NULL THEN
      v_verified := public.is_at_point(
        v_session.location_lat, v_session.location_lng,
        coalesce(v_session.location_radius_m,
                 (SELECT station_radius_m FROM public.departments WHERE id = v_dept),
                 400),
        p_lat, p_lng, p_accuracy);
    ELSE
      -- Off-site, but nobody has captured where. NEVER fall back to the station:
      -- they are not there. No clock; attendance above still stands.
      v_verified := false;
    END IF;
    v_pinned := true;   -- an off-site session is always "pinned" for gate purposes
  ELSE
    v_verified := public.is_at_station(v_dept, p_lat, p_lng, p_accuracy);
    SELECT (station_lat IS NOT NULL AND station_lng IS NOT NULL)
      INTO v_pinned
      FROM public.departments
     WHERE id = v_dept;
  END IF;
  -- ---- END CHANGED BLOCK ----

  IF v_verified OR NOT v_pinned THEN
    INSERT INTO public.station_presence (department_id, member_id, verified, source, kind, session_id)
    VALUES (v_dept, v_member, v_verified, 'geo', 'training', p_session_id)
    ON CONFLICT (member_id, session_id) WHERE kind = 'training' AND session_id IS NOT NULL DO NOTHING;
  END IF;

  IF v_recorded THEN RETURN 'recorded'; ELSE RETURN 'already'; END IF;
END;
$function$

set_drill_plan(p_id uuid, p_title text,.def:
CREATE OR REPLACE FUNCTION public.set_drill_plan(p_id uuid, p_title text, p_category text, p_duration_min integer, p_audience text, p_content jsonb, p_source text DEFAULT 'ai'::text)
 RETURNS drill_plans
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- B4C:drill plans — create (p_id null, as a draft) or edit a plan in the caller's OWN department. Edit keeps status + source.
  declare v_dept uuid := public.my_department_id(); v_me uuid := public.my_member_id(); v_row public.drill_plans;
  begin
    if v_dept is null or not coalesce(public.is_training_manager(), false) then
      raise exception 'Only a Department Admin or training officer can manage drill plans.';
    end if;
    if p_title is null or btrim(p_title) = '' then raise exception 'A drill plan needs a title.'; end if;
    if p_content is null or jsonb_typeof(p_content) <> 'object' then raise exception 'A drill plan''s content must be a JSON object.'; end if;
    if p_duration_min is not null and p_duration_min <= 0 then raise exception 'Duration must be a positive number of minutes.'; end if;
    if p_id is null then
      if p_source is null or p_source not in ('ai', 'manual') then raise exception 'A drill plan''s source must be ai or manual.'; end if;
      insert into public.drill_plans (department_id, title, category, duration_min, audience, content, source, created_by, updated_by)
      values (v_dept, btrim(p_title), nullif(btrim(p_category), ''), p_duration_min, nullif(btrim(p_audience), ''), p_content, p_source, v_me, v_me)
      returning * into v_row;
    else
      update public.drill_plans
         set title = btrim(p_title), category = nullif(btrim(p_category), ''), duration_min = p_duration_min,
             audience = nullif(btrim(p_audience), ''), content = p_content, updated_by = v_me, updated_at = now()
       where id = p_id and department_id = v_dept
      returning * into v_row;
      if not found then raise exception 'That drill plan is not in your department.'; end if;
    end if;
    return v_row;
  end;
  $function$

